using FMODUnity;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "HiddenEffect", menuName = "Data/Battle/Effects/Enemy/Hidden Effect")]
public class HiddenEffect : Effect
{
	private const string hiddenRemovedByRerollID = "HiddenRemovedByReroll";

	[Header("SFX")]
	[SerializeField]
	private EventReference hidingSFX;

	[SerializeField]
	private EventReference unhidingSFX;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string text = "";
		text = ((amount < EffectsValues.INFINITY) ? base.GetEffectDescription(amount) : ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("HiddenInf_D"));
		return text + "\n" + base.localizationManager.GetLocalizedString("HiddenRemovedByReroll");
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		effectOwner.GetComponent<CorruptedAnimalActivation>().HideDiceFace(hideDiceFace: true);
		SpriteControl spriteControl = effectOwner.GetComponent<SpriteControl>();
		if (spriteControl.HasAnimation(AnimationType.Close) && !spriteControl.IsAnimationPlaying(AnimationType.Skill))
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(hidingSFX);
		}
		else if (!spriteControl.HasAnimation(AnimationType.Close))
		{
			PlayEffectActivationSFX();
		}
		spriteControl.PlayAnimationIfSpecificAnimationIsNotPlaying(AnimationType.Close, AnimationType.Skill, AnimationChangeType.StayInTheNewAnimationNotLooping, delegate
		{
			spriteControl.PlayAnimation(AnimationType.Skill, AnimationChangeType.StayInTheNewAnimationLooping);
		});
		SpawnVFX(GetVFXOwnerPosition(effectOwner));
		return effectAmount;
	}

	public override void RemoveEffect(int effectAmount, GameObject effectOwner)
	{
		if (!effectOwner.GetComponent<UnitEffects>().IsEffectActive(this, activateFeedback: false))
		{
			effectOwner.GetComponent<CorruptedAnimalActivation>().HideDiceFace(hideDiceFace: false);
		}
	}

	public float LeaveHiddenAnimationGetHiddenAnimationTime(GameObject effectOwner)
	{
		SpriteControl component = effectOwner.GetComponent<SpriteControl>();
		if (component.HasAnimation(AnimationType.Open))
		{
			_ = component.GetCurrentTrackEntry().Animation.Duration;
			if (!component.IsAnimationPlaying(AnimationType.Skill))
			{
				ReferenceSingleton<SFXHandler>.Instance.PlaySFX(unhidingSFX);
			}
			component.PlayAnimation(AnimationType.Open, AnimationChangeType.ReturnToIdleAnimation);
			return component.GetAnimationDuration(AnimationType.Open);
		}
		return 0f;
	}
}
